import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String userId = (String) req.getSession().getAttribute("user_id");

        if (userId == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        // Input validation - allow alphanumeric and hyphens for format
        if (format != null && !format.matches("[a-zA-Z0-9\\-]+")) {
            resp.sendError(400, "Invalid format parameter");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Developer note: reportId is numeric per API spec, validated client-side
            String query = "SELECT r.title, r.content, r.created_at, u.email " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.id = " + reportId + " AND r.org_id = (" +
                          "SELECT org_id FROM users WHERE id = '" + userId + "')";

            log.info("Executing report query for user: " + userId);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{\"reports\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{\"title\":\"").append(escapeJson(rs.getString("title")))
                    .append("\",\"content\":\"").append(escapeJson(rs.getString("content")))
                    .append("\",\"created_at\":\"").append(rs.getString("created_at"))
                    .append("\",\"author_email\":\"").append(escapeJson(rs.getString("email")))
                    .append("\"}");
                first = false;
            }
            json.append("]}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String userId = (String) req.getSession().getAttribute("user_id");
        if (userId == null) { resp.sendError(401); return; }

        String title = req.getParameter("title");
        String content = req.getParameter("content");

        if (title == null || title.length() > 200 || content == null) {
            resp.sendError(400, "Invalid input");
            return;
        }

        Connection conn = null;
        PreparedStatement pstmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            pstmt = conn.prepareStatement(
                "INSERT INTO reports (title, content, author_id, org_id, created_at) " +
                "VALUES (?, ?, ?, (SELECT org_id FROM users WHERE id = ?), NOW())");
            pstmt.setString(1, title);
            pstmt.setString(2, content);
            pstmt.setString(3, userId);
            pstmt.setString(4, userId);
            pstmt.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            log.warning("Insert error: " + e.getMessage());
            resp.sendError(500, "Database error");
        } finally {
            try { if (pstmt != null) pstmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
